package io.github.jesterportfolio.hearth.phone;

import io.github.jesterportfolio.hearth.quest.GameInformation;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class PhoneGroundedFollowupTest {
    static PhoneGrounding.Plan plan(){
        var materials=new ArrayList<PhoneGrounding.Material>();for(int i=0;i<4;i++){String key="P:private_"+i;var data=new GameInformation(List.of(),List.of(),List.of(new GameInformation.Diary("PERSON","공방 "+(i+1),"공개 기록","배경. ".repeat(100)+"운반품은 "+List.of("판자","석재","실타래","철못").get(i)+"이다.",false)),List.of());var source=new PhoneRetrieval.Source("diary",i,"공방 "+(i+1),"운반품은 "+List.of("판자","석재","실타래","철못").get(i)+"이다.");materials.add(new PhoneGrounding.Material(new PhoneHelp.Selection("diary",key,data,source),1,-1));}
        return new PhoneGrounding.Plan("diary","운반품은 무엇인가요",false,materials,materials.stream().map(m->m.item().key()).collect(java.util.stream.Collectors.toSet()));
    }
    static AssistantService service(List<AssistantRequest> requests){return new AssistantService(){public CompletionStage<String> ask(String text){throw new AssertionError();}public CompletionStage<String> ask(AssistantRequest request){requests.add(request);return CompletableFuture.completedFuture("판자 [자료 1]");}};}
    static CompletionStage<Void> send(PhoneChat chat,PhoneGrounding.Plan plan){return chat.submitGroundedPreview(chat.previewGrounded(plan),plan,()->true,()->CompletableFuture.completedFuture(true));}

    @Test void followupChangesOnlyTheQuestionAndKeepsTheAnchorExcerptOrderAndScope(){var first=plan().toggle("P:private_1").sent();var next=first.followUp("그중 첫 번째는?");assertEquals("그중 첫 번째는?",next.question());assertEquals(first.retrievalQuestion(),next.retrievalQuestion());assertEquals(first.result(),next.result());assertEquals(first.scope(),next.scope());assertEquals(first.materials(),next.materials());assertEquals(3,next.materials().size());assertFalse(next.result().context().contains("석재"));assertTrue(next.result().context().contains("[자료 3]"));assertFalse(next.result().context().contains("[자료 4]"));assertEquals(first.retrievalQuestion(),next.followUp("다시 확인해").sent().retrievalQuestion());}
    @Test void singleItemFollowupRetainsTheSameSingleSourceSerialization(){var initial=plan();var material=initial.materials().getFirst();var first=new PhoneGrounding.Plan("diary","질문",true,List.of(material),Set.of(material.item().key()));var next=first.followUp("이어서 설명해");assertTrue(next.single());assertEquals(first.result(),next.result());assertEquals(first.scope(),next.scope());assertEquals("질문",next.retrievalQuestion());}
    @Test void emptyOrUnselectedBundlesAndInvalidQuestionsCannotBecomeFollowups(){var full=plan();var empty=new PhoneGrounding.Plan("diary","질문",false,List.of(),Set.of());assertThrows(IllegalStateException.class,()->empty.followUp("이어서"));var none=new PhoneGrounding.Plan(full.mode(),full.question(),false,full.materials(),Set.of());assertThrows(IllegalStateException.class,()->none.followUp("이어서"));for(String question:List.of(""," ","가".repeat(257)))assertThrows(IllegalArgumentException.class,()->full.followUp(question));assertThrows(IllegalArgumentException.class,()->full.followUp(null));assertThrows(IllegalArgumentException.class,()->new PhoneGrounding.Plan(full.mode(),full.question(),false,full.materials(),full.included(),""));}
    @Test void choicesAreSessionOwnedAndAnOldFailureCannotForgetANewerSelection(){var followups=new PhoneFollowup();Object a=new String("equal"),b=new String("equal");var old=followups.select(a,plan());var other=followups.select(b,plan());assertFalse(followups.matches(b,old));assertTrue(followups.matches(b,other));var current=followups.select(a,plan());followups.forget(a,old);assertSame(current,followups.get(a));followups.forget(b);assertNull(followups.get(b));followups.clear();assertNull(followups.get(a));}
    @Test void failedSelectionPreservesThePreviousBundleAndSelectionIsImmutable(){var followups=new PhoneFollowup();Object session=new Object();var selected=followups.select(session,plan());assertThrows(IllegalArgumentException.class,()->followups.select(session,new PhoneGrounding.Plan("diary","질문",false,List.of(),Set.of())));assertSame(selected,followups.get(session));assertThrows(UnsupportedOperationException.class,()->selected.plan().materials().clear());assertThrows(UnsupportedOperationException.class,()->selected.plan().included().clear());assertEquals(plan().result(),selected.question("다음 질문").result());}
    @Test void differentFollowupQuestionsActuallyIncludeOnlyTheSameBundlesHistory(){var requests=new ArrayList<AssistantRequest>();var chat=new PhoneChat(service(requests),Runnable::run);var first=plan();send(chat,first).toCompletableFuture().join();send(chat,first.followUp("그중 첫 번째는?")).toCompletableFuture().join();send(chat,first.followUp("이전 답변의 자료는?")).toCompletableFuture().join();assertEquals(List.of(0,1,2),requests.stream().map(r->r.history().size()).toList());assertTrue(requests.stream().allMatch(r->r.context().equals(first.result().context())&&r.sources()==4));assertEquals(first.question(),requests.get(1).history().getFirst().question());assertTrue(requests.stream().noneMatch(r->r.prompt().contains("P:private_")));}
    @Test void previewShowsTheExactBoundedHistoryAndMatchesTheSentRequest(){var requests=new ArrayList<AssistantRequest>();var chat=new PhoneChat(service(requests),Runnable::run);var first=plan();send(chat,first).toCompletableFuture().join();var next=first.followUp("이어 묻기");var preview=chat.previewGrounded(next);assertEquals(1,preview.request().history().size());assertTrue(String.join("\n",preview.lines()).contains("이전 질문: "+first.question()));assertTrue(String.join("\n",preview.lines()).contains(preview.request().context()));assertThrows(UnsupportedOperationException.class,()->preview.lines().clear());chat.submitGroundedPreview(preview,next,()->true,()->CompletableFuture.completedFuture(true)).toCompletableFuture().join();assertEquals(preview.request(),requests.getLast());}
    @Test void longHistoryPreviewDisplaysOnlyTheActual128And400CharacterTransmittedSlices(){
        var requestList=new ArrayList<AssistantRequest>();String answer="가".repeat(500)+" [자료 1]";var backend=new AssistantService(){public CompletionStage<String> ask(String q){throw new AssertionError();}public CompletionStage<String> ask(AssistantRequest request){requestList.add(request);return CompletableFuture.completedFuture(answer);}};var chat=new PhoneChat(backend,Runnable::run);send(chat,plan().followUp("나".repeat(230))).toCompletableFuture().join();var next=plan().followUp("다음 질문");var shown=chat.previewGrounded(next);var old=shown.request().history().getFirst();assertEquals(128,old.question().length());assertEquals(400,old.answer().length());assertTrue(String.join("\n",shown.lines()).contains(old.question()));assertFalse(String.join("\n",shown.lines()).contains(answer));chat.submitGroundedPreview(shown,next,()->true,()->CompletableFuture.completedFuture(true)).toCompletableFuture().join();assertEquals(shown.request(),requestList.getLast());
    }
    @Test void previewRejectsCrossChatChangedHistoryAndHistoryChoiceBeforeSending(){var requests=new ArrayList<AssistantRequest>();var chat=new PhoneChat(service(requests),Runnable::run);var other=new PhoneChat(service(requests),Runnable::run);var first=plan();var preview=chat.previewGrounded(first);assertFalse(other.groundedPreviewCurrent(preview,first));assertTrue(other.submitGroundedPreview(preview,first,()->true,()->CompletableFuture.completedFuture(true)).toCompletableFuture().isCompletedExceptionally());assertTrue(requests.isEmpty());send(chat,first).toCompletableFuture().join();assertFalse(chat.groundedPreviewCurrent(preview,first));var withHistory=chat.previewGrounded(first.followUp("이어서"));chat.includeHistory(false);assertFalse(chat.groundedPreviewCurrent(withHistory,first.followUp("이어서")));assertEquals(1,requests.size());}
    @Test void fullMaterialVersionIsPartOfPreviewEvenWhenTheVisibleExcerptHasNotChanged(){var chat=new PhoneChat(service(new ArrayList<>()),Runnable::run);var first=plan().sent();var preview=chat.previewGrounded(first);var materials=new ArrayList<>(first.materials());var old=materials.getFirst();materials.set(0,new PhoneGrounding.Material(old.item(),2,old.objective()));var changed=new PhoneGrounding.Plan(first.mode(),first.question(),false,materials,first.included());assertEquals(preview.request().context(),chat.previewGrounded(changed).request().context());assertFalse(chat.groundedPreviewCurrent(preview,changed));assertTrue(chat.submitGroundedPreview(preview,changed,()->true,()->CompletableFuture.completedFuture(true)).toCompletableFuture().isCompletedExceptionally());}
    @Test void excludingMaterialsIsAnExplicitNewScopeAndNeverBringsBackOldNumberMeanings(){var requests=new ArrayList<AssistantRequest>();var chat=new PhoneChat(service(requests),Runnable::run);var first=plan();send(chat,first).toCompletableFuture().join();var reduced=first.toggle("P:private_0").sent().followUp("그중 첫 번째는?");var preview=chat.previewGrounded(reduced);assertTrue(preview.request().history().isEmpty());assertEquals(3,preview.request().sources());assertFalse(preview.request().context().contains("판자"));assertTrue(preview.request().context().contains("[자료 1] 공방 2"));}
    @Test void followupCacheStillValidatesEveryResponseAndDoesNotRequireSendingHistory(){var generated=new AtomicInteger();var confirmed=new AtomicInteger();var validated=new AtomicInteger();var backend=new AssistantService(){public boolean allowsCache(){return true;}public CompletionStage<String> ask(String q){generated.incrementAndGet();return CompletableFuture.completedFuture("판자 [자료 1]");}public CompletionStage<String> confirmCached(String value){confirmed.incrementAndGet();return CompletableFuture.completedFuture(value);}};var chat=new PhoneChat(backend,Runnable::run);chat.includeHistory(false);var next=plan().followUp("첫 번째는?");for(int i=0;i<2;i++)chat.submitGroundedPreview(chat.previewGrounded(next),next,()->true,()->{validated.incrementAndGet();return CompletableFuture.completedFuture(true);}).toCompletableFuture().join();assertEquals(1,generated.get());assertEquals(1,confirmed.get());assertEquals(2,validated.get());assertEquals(2,chat.history().size());}
    @Test void losingTheChosenBundleDuringGenerationRejectsTheLateAnswerAndPreservesDraft(){var answer=new CompletableFuture<String>();var chat=new PhoneChat(q->answer,Runnable::run);var selections=new PhoneFollowup();Object session=new Object();var choice=selections.select(session,plan());var next=choice.question("이어서 질문");var work=chat.submitGroundedPreview(chat.previewGrounded(next),next,()->selections.matches(session,choice),()->CompletableFuture.completedFuture(true));selections.forget(session);answer.complete("판자 [자료 1]");assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertTrue(chat.history().isEmpty());assertEquals("이어서 질문",chat.draft());assertEquals(0,chat.cacheStats().entries());}
    @Test void failedPostValidationKeepsDraftAndHistoryAndNeverCachesTheResponse(){var chat=new PhoneChat(LocalAssistant.mock(),Runnable::run);var next=plan().followUp("보존할 질문");var work=chat.submitGroundedPreview(chat.previewGrounded(next),next,()->true,()->CompletableFuture.failedFuture(new IllegalStateException("PG_READ_FAILED")));assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals("보존할 질문",chat.draft());assertTrue(chat.history().isEmpty());assertEquals(0,chat.cacheStats().entries());}
    @Test void closingOrClearingChatRetiresOldPreviewWithoutDiscardingAnIndependentChoice(){var chat=new PhoneChat(LocalAssistant.mock(),Runnable::run);var choices=new PhoneFollowup();Object session=new Object();var choice=choices.select(session,plan());send(chat,plan()).toCompletableFuture().join();var preview=chat.previewGrounded(choice.question("다음"));chat.clear();assertFalse(chat.groundedPreviewCurrent(preview,choice.question("다음")));assertSame(choice,choices.get(session));var newPreview=chat.previewGrounded(choice.question("다음"));chat.close();assertFalse(chat.groundedPreviewCurrent(newPreview,choice.question("다음")));}
}
